			    if(pwlen > 255) pwlen = 255;
			    if((unsigned)pwlen < pwl_table.recsize) {
				memset(buf, 0, pwl_table.recsize - 1);
				memcpy(buf, param->password, pwlen);
				if(!ctmemcmp(pass + 1, buf, pwl_table.recsize - 1)) return 0;
			    } else {
				mdh_ctx *bctx;
				unsigned hashsz;
