	int chunked;
	uint64_t sent = 0;

	size = qparam((const char *)params, "size", 0);
	size = qparam(r->query, "size", size);
	if(size < 0) size = 0;
	block = qparam((const char *)params, "block", HTTPSRV_BLOCK);
	block = qparam(r->query, "block", block);
