+	if(!res) return "allow";
+	if(res == 10) return "limit";
+	if(action == DENY || res == 1 || res == 3) return "deny";
+	if(res == 4) return "auth_required";
+	if(res >= 5 && res <= 9) return "auth_failed";
+	if(res < 100) return "denied";
+	return "error";
