	auditprintf(&line, " client=");
	audittoken(&line, (unsigned char *)ip);
	auditprintf(&line, ":%hu", ntohs(*SAPORT(&param->sincr)));

	target = (param->hostname && *param->hostname)? param->hostname : NULL;
	if(!target){
		if(*SAFAMILY(&param->req) == AF_INET
